select
    s.sno 'sno', s.sname 'sname', sc.cno 'cno', sc.score 'score'
from students s left join sc on s.sno = sc.sno;

select
    e.Eid 'Eid', e.EName 'EName', w.Wno 'Wno', w.City 'City'
from employee e left join warehouse w on e.Wno = w.Wno;

select d.deptno 'deptno', d.dname 'dname' from dept d left join emp e on d.deptno = e.deptno
group by d.deptno, d.dname
order by count(e.empno) desc limit 1;
